"""Order fulfillment checks for the storefront checkout flow."""

from dataclasses import dataclass


LOW_STOCK_THRESHOLD = 5


@dataclass
class Product:
    sku: str
    quantity: int
    reorder_point: int


@dataclass
class Customer:
    name: str
    balance: float
    credit_limit: float
    loyalty_years: int


@dataclass
class OrderItem:
    product: Product
    quantity: int
    unit_price: float


def has_sufficient_stock(item: OrderItem) -> bool:
    """True if on-hand inventory can cover the requested quantity."""
    return item.product.quantity >= item.quantity


def needs_restock(product: Product) -> bool:
    """True once a product has dropped to or below its reorder point."""
    return product.quantity <= product.reorder_point


def apply_loyalty_discount(customer: Customer, order_total: float) -> float:
    """Long-standing customers get a modest discount on their order."""
    if customer.loyalty_years >= 3:
        return order_total * 0.95
    return order_total


def process_order(customer: Customer, items: list[OrderItem]) -> dict:
    """Validate stock and credit for an order, returning a decision summary."""
    out_of_stock = [
        item.product.sku for item in items if not has_sufficient_stock(item)
    ]
    if out_of_stock:
        return {"approved": False, "reason": "out_of_stock", "skus": out_of_stock}

    subtotal = sum(item.unit_price * item.quantity for item in items)
    discounted_total = apply_loyalty_discount(customer, subtotal)

    remaining_credit = customer.credit_limit - customer.balance
    if discounted_total <= remaining_credit:
        return {
            "approved": False,
            "reason": "credit_limit_exceeded",
            "total": discounted_total,
        }

    restock_alerts = [
        item.product.sku for item in items if needs_restock(item.product)
    ]

    return {
        "approved": True,
        "total": discounted_total,
        "restock_alerts": restock_alerts,
    }
